WHERE cycle_products.status >= 0

  AND cycle_products.reference LIKE CONCAT("%", #{filter.searchText}, "%")


  AND cycle_products.date = #{filter.date}


  AND cycle_products.cp_type = #{filter.cpType}


  AND cycle_products.adj_type = #{filter.type}


  AND cycle_products.location_group_id = #{filter.warehouseId}


  AND cycle_products.status = #{filter.status}


  AND cycle_products.created_by = #{userId}

mapper.select:
SELECT



ORDER BY


    ${filter.orderBy}


    cycle_products.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM cycle_products
WHERE status <= 1 AND reference = #{code}
 AND id != #{id}

mapper.update:
UPDATE cycle_products SET
  status = -1,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id};

UPDATE cycle_products SET
  status = 0,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id};

UPDATE cycle_products SET
  status = #{filter.status},
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{filter.id};

mapper.select:
SELECT reference
FROM cycle_products
WHERE id = #{id}

SELECT cp_type
FROM cycle_products
WHERE id = #{id}

SELECT adj_type
FROM cycle_products
WHERE id = #{id}

SELECT SUM((total_cycle + total_to_in + total_cm + total_pb) - (total_so + total_pos + total_pbc + total_to_out)) AS total_qty
FROM ${tableNameDetail}
WHERE product_id = #{filter.productId}
  AND lots_number = (SELECT lots_number FROM ${tableNameDetail} WHERE product_id = #{filter.productId} ORDER BY product_id DESC LIMIT 1)

    AND expired_date = (SELECT expired_date FROM ${tableNameDetail} WHERE product_id = #{filter.productId} ORDER BY product_id DESC LIMIT 1)

  AND date <= #{filter.date}
GROUP BY product_id

  , expired_date
